using System.Net; using System.Threading; using Ae.Dns.Client; using Ae.Dns.Protocol; using Ae.Dns.Protocol.Enums; class Program { static async System.Threading.Tasks.Task Main() { using var client = new DnsUdpClient(IPAddress.Parse("223.5.5.5")); var msg = await client.Query(DnsQueryFactory.CreateQuery("_pclcesyn._tcp.example.com", DnsQueryType.SRV), CancellationToken.None); System.Console.WriteLine($"Answers: {msg.Answers.Count}"); foreach (var a in msg.Answers) { System.Console.WriteLine($"Type: {a.Type}, Target: {((Ae.Dns.Protocol.Records.DnsSrvResource)a.Resource).Target}"); } } }
